sp_widget.client_script:
api.controller = function($scope, $window, $timeout) {

  var c = this;


  /* =====================================================
     SIDEBAR
  ====================================================== */

  c.sidebarCollapsed = false;


  c.toggleSidebar = function() {

    c.sidebarCollapsed = !c.sidebarCollapsed;

    if (!$scope.$$phase) {
      $scope.$applyAsync();
    }

  };


  /* =====================================================
     BASIC PAGE STATE
  ====================================================== */

  c.searchText = "";
  c.globalSearch = "";


  c.filters = {
    industry: "",
    companyType: "",
    status: ""
  };


  c.filteredCompanies = [];
  c.selectedCompany = null;


  /* =====================================================
     ADD COMPANY STATE
  ====================================================== */

  c.showAddCompany = false;

  c.savingCompany = false;

  c.addCompanyMessage = "";

  c.newCompany = {
    company_name: "",
    company_id: "",
    industry: "",
    recruiter_name: "",
    recruiter_email: "",
    contact_number: "",
    company_type: "",
    status: "Active"
  };


  /* =====================================================
     INITIALIZE
  ====================================================== */

  c.initialize = function() {

    c.filteredCompanies =
      angular.copy(
        c.data.companies || []
      );

  };


  /* =====================================================
     NAVIGATION
  ====================================================== */




  /* =====================================================
     REFRESH
  ====================================================== */

  c.refresh = function() {

    $window.location.reload();

  };


  /* =====================================================
     GLOBAL SEARCH
  ====================================================== */

  c.syncGlobalSearch = function() {

    c.searchText =
      c.globalSearch || "";

    c.applyFilters();

  };


  /* =====================================================
     FILTERING
  ====================================================== */

  c.applyFilters = function() {

    var search =
      String(c.searchText || "")
        .toLowerCase()
        .trim();


    c.filteredCompanies =
      (c.data.companies || []).filter(
        function(company) {

          var matchesSearch = true;
          var matchesIndustry = true;
          var matchesCompanyType = true;
          var matchesStatus = true;


          /* SEARCH */

          if (search) {

            var searchableText = [

              company.company_name,
              company.company_id,
              company.industry,
              company.recruiter_name,
              company.recruiter_email,
              company.contact_number,
              company.company_type,
              company.status

            ].join(" ").toLowerCase();


            matchesSearch =
              searchableText.indexOf(search) !== -1;

          }


          /* INDUSTRY */

          if (c.filters.industry) {

            matchesIndustry =
              String(
                company.industry || ""
              ).toLowerCase().trim() ===
              String(
                c.filters.industry || ""
              ).toLowerCase().trim();

          }


          /* COMPANY TYPE */

          if (c.filters.companyType) {

            matchesCompanyType =
              String(
                company.company_type || ""
              ).toLowerCase().trim() ===
              String(
                c.filters.companyType || ""
              ).toLowerCase().trim();

          }


          /* STATUS */

          if (c.filters.status) {

            matchesStatus =
              String(
                company.status || ""
              ).toLowerCase().trim() ===
              String(
                c.filters.status || ""
              ).toLowerCase().trim();

          }


          return (
            matchesSearch &&
            matchesIndustry &&
            matchesCompanyType &&
            matchesStatus
          );

        }
      );

  };


  /* =====================================================
     CLEAR FILTERS
  ====================================================== */

  c.clearFilters = function() {

    c.searchText = "";
    c.globalSearch = "";


    c.filters = {
      industry: "",
      companyType: "",
      status: ""
    };


    c.applyFilters();

  };


  /* =====================================================
     COMPANY MODAL
  ====================================================== */

  c.openCompany = function(company) {

    if (!company) {
      return;
    }


    c.selectedCompany = company;


    try {

      document.body.style.overflow = "hidden";

    } catch (e) {}

  };


  c.closeCompany = function() {

    c.selectedCompany = null;


    try {

      document.body.style.overflow = "";

    } catch (e) {}

  };


  /* =====================================================
     ADD COMPANY
     THIS WAS MISSING
  ====================================================== */

  c.openAddCompany = function() {

    /*
     * Close the View Company modal if it happens
     * to be open.
     */

    c.selectedCompany = null;


    /*
     * Reset the form every time Add Company
     * is opened.
     */

    c.newCompany = {

      company_name: "",
      company_id: "",
      industry: "",
      recruiter_name: "",
      recruiter_email: "",
      contact_number: "",
      company_type: "",
      status: "Active"

    };


    c.addCompanyMessage = "";

    c.savingCompany = false;

    c.showAddCompany = true;


    /*
     * Prevent background page scrolling
     * while modal is open.
     */

    try {

      document.body.style.overflow = "hidden";

    } catch (e) {}

  };


  /* =====================================================
     CLOSE ADD COMPANY
  ====================================================== */

  c.closeAddCompany = function() {

    if (c.savingCompany) {
      return;
    }


    c.showAddCompany = false;

    c.addCompanyMessage = "";


    try {

      document.body.style.overflow = "";

    } catch (e) {}

  };


  /* =====================================================
     SAVE COMPANY
  ====================================================== */

  c.saveCompany = function() {

    /*
     * Prevent double clicking.
     */

    if (c.savingCompany) {
      return;
    }


    var company =
      angular.copy(
        c.newCompany
      );


    /*
     * Required validation
     */

    company.company_name =
      String(
        company.company_name || ""
      ).trim();


    company.company_id =
      String(
        company.company_id || ""
      ).trim();


    if (!company.company_name) {

      c.addCompanyMessage =
        "Company Name is required.";

      return;

    }


    if (!company.company_id) {

      c.addCompanyMessage =
        "Company ID is required.";

      return;

    }


    /*
     * Default status
     */

    if (!company.status) {

      company.status = "Active";

    }


    /*
     * Start saving
     */

    c.savingCompany = true;

    c.addCompanyMessage =
      "Saving company...";


    /*
     * Send the record to the Server Script.
     *
     * The Server Script already handles:
     * input.action === "add_company"
     */

    c.server.get({

      action: "add_company",

      company: company

    }).then(
      function(response) {

        /*
         * Replace current widget data with
         * the refreshed server response.
         */

        if (
          response &&
          response.data
        ) {

          c.data =
            response.data;

        }


        /*
         * Check server result.
         */

        if (
          response &&
          response.data &&
          response.data.success
        ) {

          /*
           * Rebuild filtered list using
           * the newly returned company data.
           */

          c.filteredCompanies =
            angular.copy(
              c.data.companies || []
            );


          /*
           * Re-apply current search/filter
           * selections.
           */

          c.applyFilters();


          /*
           * Close modal after successful insert.
           */

          c.showAddCompany = false;

          c.addCompanyMessage = "";

          c.savingCompany = false;


          try {

            document.body.style.overflow = "";

          } catch (e) {}


        } else {

          /*
           * Server rejected the record.
           * Keep the modal open so the user
           * can correct the data.
           */

          c.savingCompany = false;

          c.addCompanyMessage =
            (
              response &&
              response.data &&
              response.data.message
            )
              ?
              response.data.message
              :
              "Company could not be added.";

        }

      },
      function(error) {

        /*
         * Request/server error.
         */

        c.savingCompany = false;

        c.addCompanyMessage =
          "Unable to save the company. Please try again.";

        console.error(
          "Campus360 Add Company Error:",
          error
        );

      }
    );

  };


  /* =====================================================
     COMPANY INITIALS
  ====================================================== */

  c.getInitials = function(name) {

    if (!name) {
      return "?";
    }


    var parts =
      String(name)
        .trim()
        .split(/\s+/);


    if (parts.length === 1) {

      return parts[0]
        .substring(0, 2)
        .toUpperCase();

    }


    return (
      parts[0].charAt(0) +
      parts[parts.length - 1].charAt(0)
    ).toUpperCase();

  };


  /* =====================================================
     STATUS CLASS
  ====================================================== */

  c.getStatusClass = function(status) {

    var value =
      String(status || "")
        .toLowerCase()
        .trim();


    if (value === "active") {

      return "company-status-active";

    }


    if (value === "inactive") {

      return "company-status-inactive";

    }


    return "company-status-other";

  };


  /* =====================================================
     ESCAPE KEY
  ====================================================== */

  angular.element(document).on(
    "keydown.campus360CompanyManagement",
    function(event) {

      if (
        event.key === "Escape"
      ) {

        if (c.showAddCompany) {

          $scope.$applyAsync(
            function() {

              c.closeAddCompany();

            }
          );

          return;

        }


        if (c.selectedCompany) {

          $scope.$applyAsync(
            function() {

              c.closeCompany();

            }
          );

        }

      }

    }
  );


  /* =====================================================
     CLEANUP
  ====================================================== */

  $scope.$on(
    "$destroy",
    function() {

      try {

        angular.element(document).off(
          "keydown.campus360CompanyManagement"
        );

        document.body.style.overflow = "";

      } catch (e) {}

    }
  );


  /* =====================================================
     START
  ====================================================== */

  c.initialize();


    c.goTo = function(pageId) {
        if (!pageId) return;
        var map = {
            'dashboard': 'campus360_tpo_home',
            'home': 'campus360_tpo_home',
            'campus360_tpo_home': 'campus360_tpo_home',
            'students': 'campus360_tpo_student_management',
            'student_management': 'campus360_tpo_student_management',
            'campus360_tpo_student_management': 'campus360_tpo_student_management',
            'skills': 'campus360_tpo_skill_intelligence_new',
            'skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence': 'campus360_tpo_skill_intelligence_new',
            'campus360_tpo_skill_intelligence_new': 'campus360_tpo_skill_intelligence_new',
            'assessments': 'student_assessments_new',
            'student_assessments': 'student_assessments_new',
            'student_assessments_new': 'student_assessments_new',
            'companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies': 'campus360_tpo_companies_new',
            'campus360_tpo_companies_new': 'campus360_tpo_companies_new',
            'opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities': 'campus360_tpo_opportunities_new',
            'campus360_tpo_opportunities_new': 'campus360_tpo_opportunities_new',
            'applications': 'campus360_tpo_application_new',
            'application': 'campus360_tpo_application_new',
            'campus360_tpo_application': 'campus360_tpo_application_new',
            'campus360_tpo_application_new': 'campus360_tpo_application_new',
            'interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_interviews_new': 'campus360_tpo_interviews_new',
            'outcomes': 'campus360_tpo_placement_outcomes',
            'placement_outcomes': 'campus360_tpo_placement_outcomes',
            'campus360_tpo_placement_outcomes': 'campus360_tpo_placement_outcomes',
            'training': 'campus360_tpo_training_programs',
            'training_programs': 'campus360_tpo_training_programs',
            'campus360_tpo_training_programs': 'campus360_tpo_training_programs',
            'enrollments': 'campus360_tpo_training_programs',
            'campus360_tpo_enrollments': 'campus360_tpo_training_programs',
            'mock_interviews': 'campus360_tpo_interviews_new',
            'campus360_tpo_mock_interviews': 'campus360_tpo_interviews_new',
            'risk': 'campus360_tpo_student_management',
            'campus360_tpo_risk_intelligence': 'campus360_tpo_student_management',
            'interventions': 'campus360_tpo_student_management',
            'campus360_tpo_interventions': 'campus360_tpo_student_management',
            'readiness': 'campus360_tpo_skill_intelligence_new',
            'ai_assistant': 'campus360_tpo_ai_assistant',
            'campus360_tpo_ai_assistant': 'campus360_tpo_ai_assistant'
        };
        var target = map[pageId] || pageId;
        if (typeof $window !== 'undefined' && $window.location) {
            $window.location.href = '?id=' + encodeURIComponent(target);
        } else {
            window.location.href = '?id=' + encodeURIComponent(target);
        }
    };
    c.goToPage = function(pageId) { c.goTo(pageId); };
    c.navigate = function(pageId) { c.goTo(pageId); };

};

sp_widget.css:
/* =========================================================
   CAMPUS360 COMPANY MANAGEMENT
   COMPLETE FINAL CSS
   FULL SCREEN
   NATIVE SERVICENOW HEADER HIDDEN
   CAMPUS360 NAVBAR PROPERLY STYLED
   ========================================================= */


/* =========================================================
   1. GLOBAL PAGE RESET
   ========================================================= */

html,
body {
  width:100% !important;
  height:100% !important;

  min-width:100% !important;
  min-height:100% !important;

  margin:0 !important;
  padding:0 !important;

  overflow:hidden !important;

  background:#f5f7fb !important;
}


/* =========================================================
   2. REMOVE SERVICENOW OUTER CONSTRAINTS
   ========================================================= */

body:has(.campus360-company-app) #sp-page,
body:has(.campus360-company-app) #sp-main,
body:has(.campus360-company-app) .sp-page,
body:has(.campus360-company-app) .sp-main,
body:has(.campus360-company-app) .sp-page-container,
body:has(.campus360-company-app) #page_content,
body:has(.campus360-company-app) .page,
body:has(.campus360-company-app) .page-wrapper,
body:has(.campus360-company-app) .main-content,
body:has(.campus360-company-app) .container,
body:has(.campus360-company-app) .container-fluid,
body:has(.campus360-company-app) .row {
  width:100% !important;
  max-width:none !important;
  min-width:0 !important;

  margin:0 !important;
  padding:0 !important;

  border:0 !important;
}


/* =========================================================
   3. COMPLETELY HIDE NATIVE SERVICENOW NAVBAR
   ========================================================= */

body:has(.campus360-company-app) #sp-header,
body:has(.campus360-company-app) header#sp-header,
body:has(.campus360-company-app) .sp-header,
body:has(.campus360-company-app) .sp-header-wrapper,
body:has(.campus360-company-app) .sp-header-content,

body:has(.campus360-company-app) .sp-navbar,
body:has(.campus360-company-app) .sp-navbar-wrapper,
body:has(.campus360-company-app) .sp-navbar-container,

body:has(.campus360-company-app) #sp-nav-bar,
body:has(.campus360-company-app) .sp-nav-bar,
body:has(.campus360-company-app) .sp-nav,

body:has(.campus360-company-app) .portal-header,
body:has(.campus360-company-app) .portal-navbar,
body:has(.campus360-company-app) .portal-nav,
body:has(.campus360-company-app) .header-nav,

body:has(.campus360-company-app) .navpage-header,
body:has(.campus360-company-app) .navpage-header-content,

body:has(.campus360-company-app) .navbar,
body:has(.campus360-company-app) nav.navbar,
body:has(.campus360-company-app) header.navbar,
body:has(.campus360-company-app) .navbar-default,
body:has(.campus360-company-app) .navbar-inverse,
body:has(.campus360-company-app) .navbar-header,
body:has(.campus360-company-app) .navbar-collapse {
  display:none !important;
  visibility:hidden !important;

  width:0 !important;
  height:0 !important;

  min-width:0 !important;
  min-height:0 !important;

  max-width:0 !important;
  max-height:0 !important;

  margin:0 !important;
  padding:0 !important;

  overflow:hidden !important;
}


/* =========================================================
   4. CAMPUS360 APPLICATION
   ========================================================= */

.campus360-company-app {
  position:fixed !important;

  top:0 !important;
  left:0 !important;
  right:0 !important;
  bottom:0 !important;

  width:100vw !important;
  height:100vh !important;

  min-width:0 !important;
  min-height:0 !important;

  max-width:none !important;

  margin:0 !important;
  padding:0 !important;

  overflow:hidden !important;

  background:#f5f7fb !important;

  color:#172033 !important;

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    Helvetica,
    Arial,
    sans-serif;

  font-size:14px;

  z-index:2147483647 !important;

  isolation:isolate;

  box-sizing:border-box;
}


.campus360-company-app *,
.campus360-company-app *::before,
.campus360-company-app *::after {
  box-sizing:border-box;
}


.campus360-company-app button,
.campus360-company-app input,
.campus360-company-app select,
.campus360-company-app textarea,
.campus360-company-app a {
  font-family:inherit;
}


/* =========================================================
   5. SIDEBAR
   ========================================================= */

.company-sidebar {
  position:absolute !important;

  top:0 !important;
  left:0 !important;
  bottom:0 !important;

  width:230px !important;
  min-width:230px !important;
  max-width:230px !important;

  height:100vh !important;

  margin:0 !important;
  padding:0 !important;

  display:flex !important;
  flex-direction:column !important;

  background:
    linear-gradient(
      180deg,
      #100c27 0%,
      #15102f 52%,
      #0d0921 100%
    ) !important;

  border-right:1px solid #251d45 !important;

  color:#fff !important;

  overflow-x:hidden !important;
  overflow-y:auto !important;

  scrollbar-width:none !important;
  -ms-overflow-style:none !important;

  z-index:200 !important;

  transition:
    width .25s ease,
    min-width .25s ease,
    transform .25s ease,
    opacity .2s ease;
}


.company-sidebar::-webkit-scrollbar {
  width:0 !important;
  height:0 !important;
  display:none !important;
}


/* =========================================================
   6. SIDEBAR BRAND
   ========================================================= */

.sidebar-brand {
  height:76px !important;
  min-height:76px !important;

  padding:14px 18px !important;

  display:flex !important;
  align-items:center !important;

  gap:11px;

  border-bottom:1px solid #241c43 !important;

  flex-shrink:0;
}


.brand-logo {
  width:44px;
  height:44px;

  min-width:44px;

  border-radius:12px;

  background:
    linear-gradient(
      135deg,
      #8b5cf6,
      #6d28d9
    );

  color:#fff;

  display:flex;
  align-items:center;
  justify-content:center;

  font-size:24px;
  font-weight:900;

  box-shadow:
    0 7px 18px rgba(123,63,240,.30);
}


.brand-text {
  min-width:0;
}


.brand-title {
  color:#fff;

  font-size:18px;

  line-height:1.1;

  font-weight:900;

  white-space:nowrap;
}


.brand-subtitle {
  margin-top:4px;

  color:#b9a8f3;

  font-size:10px;

  font-weight:800;

  letter-spacing:.65px;
}


/* =========================================================
   7. TPO PROFILE
   ========================================================= */

.tpo-profile {
  margin:15px 11px !important;

  padding:13px 11px !important;

  border-radius:14px !important;

  background:#1b1539 !important;

  border:1px solid #302356 !important;

  display:flex !important;

  align-items:center !important;

  gap:10px;

  flex-shrink:0;
}


.profile-avatar {
  width:44px;
  height:44px;

  min-width:44px;

  border-radius:50%;

  background:
    linear-gradient(
      135deg,
      #8b5cf6,
      #6935df
    );

  color:#fff;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:13px;

  font-weight:900;
}


.profile-info {
  min-width:0;
}


.profile-name {
  color:#fff;

  font-size:13px;

  font-weight:900;
}


.profile-role {
  margin-top:3px;

  color:#bba8f4;

  font-size:10px;

  font-weight:800;
}


.profile-office {
  margin-top:3px;

  color:#aaa3bd;

  font-size:8px;

  font-weight:600;

  white-space:nowrap;
}


/* =========================================================
   8. SIDEBAR NAVIGATION
   ========================================================= */

.sidebar-navigation {
  flex:1 1 auto;

  min-height:0;

  padding:2px 10px 25px !important;

  overflow-y:auto !important;
  overflow-x:hidden !important;

  scrollbar-width:none !important;
  -ms-overflow-style:none !important;
}


.sidebar-navigation::-webkit-scrollbar {
  width:0 !important;
  height:0 !important;
  display:none !important;
}


.nav-section-title {
  margin:15px 12px 7px;

  color:#928ba6;

  font-size:9px;

  font-weight:900;

  letter-spacing:1.3px;
}


.sidebar-nav-item {
  width:100%;

  min-height:39px;

  margin:3px 0;

  padding:0 11px;

  display:flex;

  align-items:center;

  gap:9px;

  border-radius:9px;

  background:transparent !important;

  color:#ebe8f5 !important;

  text-decoration:none !important;

  cursor:pointer;

  font-size:12px;

  font-weight:650;

  transition:
    background .16s ease,
    color .16s ease,
    transform .16s ease;
}


.sidebar-nav-item:hover {
  background:#211a43 !important;

  color:#fff !important;

  transform:translateX(2px);

  text-decoration:none !important;
}


.sidebar-nav-item.active {
  background:
    linear-gradient(
      90deg,
      #7b3ff0,
      #8643ed
    ) !important;

  color:#fff !important;

  font-weight:900;

  box-shadow:
    0 6px 14px rgba(123,63,240,.24);
}


.nav-icon {
  width:20px;

  min-width:20px;

  text-align:center;

  color:#b8b0cb;

  font-size:15px;
}


.sidebar-nav-item.active .nav-icon,
.sidebar-nav-item:hover .nav-icon {
  color:#fff;
}


.nav-label {
  flex:1;

  min-width:0;

  white-space:nowrap;
}


.nav-count {
  min-width:22px;

  height:22px;

  padding:0 6px;

  border-radius:50%;

  display:flex;

  align-items:center;

  justify-content:center;

  background:#33235f;

  color:#d8c9ff;

  font-size:9px;

  font-weight:900;

  flex-shrink:0;
}


/* =========================================================
   9. MAIN APPLICATION AREA
   ========================================================= */

.company-main {
  position:absolute !important;

  top:0 !important;
  right:0 !important;
  bottom:0 !important;
  left:230px !important;

  width:calc(100vw - 230px) !important;

  height:100vh !important;

  min-width:0 !important;
  max-width:none !important;

  margin:0 !important;
  padding:0 !important;

  background:#f5f7fb !important;

  overflow-x:hidden !important;
  overflow-y:auto !important;

  scrollbar-width:thin;

  scrollbar-color:
    #b9afd1
    #f1f3f6;

  z-index:50 !important;

  transition:
    left .25s ease,
    width .25s ease;
}


/* RIGHT PAGE SCROLLBAR */

.company-main::-webkit-scrollbar {
  width:9px !important;
}


.company-main::-webkit-scrollbar-track {
  background:#f1f3f6 !important;
}


.company-main::-webkit-scrollbar-thumb {
  background:#b9afd1 !important;

  border-radius:10px !important;

  border:2px solid #f1f3f6 !important;
}


.company-main::-webkit-scrollbar-thumb:hover {
  background:#9886bd !important;
}


/* =========================================================
   10. CUSTOM CAMPUS360 TOP NAVBAR
   ========================================================= */

.company-topbar {
  position:sticky !important;

  top:0 !important;

  z-index:1000 !important;

  width:100% !important;

  height:72px !important;

  min-height:72px !important;

  margin:0 !important;

  padding:0 24px !important;

  display:flex !important;

  align-items:center !important;

  justify-content:space-between !important;

  background:#ffffff !important;

  border-bottom:1px solid #e4e8ef !important;

  box-shadow:
    0 1px 3px rgba(25,31,48,.025) !important;
}


/* =========================================================
   11. TOPBAR LEFT
   ========================================================= */

.topbar-left {
  min-width:0;

  display:flex;

  align-items:center;

  gap:16px;

  flex-shrink:1;
}


.sidebar-toggle {
  width:43px !important;

  height:43px !important;

  min-width:43px !important;

  padding:0 !important;

  border:1px solid #dfe3ea !important;

  border-radius:11px !important;

  background:#ffffff !important;

  color:#58657a !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:19px !important;

  line-height:1 !important;

  cursor:pointer !important;

  outline:none !important;

  box-shadow:none !important;

  transition:
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    transform .15s ease;
}


.sidebar-toggle:hover {
  background:#f7f2ff !important;

  border-color:#d0c1f2 !important;

  color:#6837d6 !important;
}


.sidebar-toggle:active {
  transform:scale(.95);
}


/* =========================================================
   12. CAMPUS360 PAGE TITLE
   ========================================================= */

.breadcrumb {
  min-width:0;

  display:flex;

  flex-direction:column;

  justify-content:center;

  gap:3px;

  white-space:nowrap;
}


.breadcrumb-small {
  color:#723bd7;

  font-size:8px;

  font-weight:950;

  letter-spacing:1.65px;

  line-height:1;
}


.breadcrumb-title {
  color:#141d30;

  font-size:17px;

  font-weight:950;

  line-height:1.1;

  letter-spacing:-.2px;
}


/* =========================================================
   13. TOPBAR RIGHT
   ========================================================= */

.topbar-right {
  min-width:0;

  display:flex;

  align-items:center;

  justify-content:flex-end;

  gap:9px;

  margin-left:auto;

  flex-shrink:0;
}


/* =========================================================
   14. NAVBAR SEARCH
   ========================================================= */

.global-search {
  width:315px !important;

  height:42px !important;

  min-width:230px !important;

  padding:0 13px !important;

  border:1px solid #dfe4ec !important;

  border-radius:11px !important;

  background:#ffffff !important;

  display:flex !important;

  align-items:center !important;

  gap:8px;

  flex-shrink:1;

  transition:
    border-color .15s ease,
    box-shadow .15s ease,
    background .15s ease;
}


.global-search:hover {
  border-color:#d7dce6 !important;
}


.global-search:focus-within {
  background:#fff !important;

  border-color:#a88be8 !important;

  box-shadow:
    0 0 0 3px rgba(123,63,240,.08) !important;
}


.global-search-icon {
  color:#6f3ce0;

  font-size:18px;

  line-height:1;

  flex-shrink:0;
}


.global-search input {
  width:100% !important;

  min-width:0 !important;

  height:100% !important;

  padding:0 !important;

  margin:0 !important;

  border:0 !important;

  outline:0 !important;

  background:transparent !important;

  color:#29334a !important;

  font-size:11px !important;

  font-weight:600 !important;

  box-shadow:none !important;
}


.global-search input::placeholder {
  color:#929aaa;
}


/* =========================================================
   15. REFRESH BUTTON
   ========================================================= */

.topbar-circle-button {
  position:relative;

  width:42px !important;

  height:42px !important;

  min-width:42px !important;

  padding:0 !important;

  border-radius:50% !important;

  border:1px solid #dfe3eb !important;

  background:#ffffff !important;

  color:#59667a !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:18px !important;

  line-height:1 !important;

  cursor:pointer !important;

  outline:none !important;

  box-shadow:none !important;

  transition:
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    transform .15s ease;
}


.topbar-circle-button:hover {
  background:#f7f2ff !important;

  border-color:#d1c1f3 !important;

  color:#6736d5 !important;
}


.topbar-circle-button:active {
  transform:scale(.95);
}


/* =========================================================
   16. BELL BUTTON
   IMPORTANT:
   HTML USES .topbar-icon-button
   ========================================================= */

.topbar-icon-button {
  position:relative !important;

  width:42px !important;

  height:42px !important;

  min-width:42px !important;

  padding:0 !important;

  margin:0 !important;

  border-radius:50% !important;

  border:1px solid #dfe3eb !important;

  background:#ffffff !important;

  color:#59667a !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:17px !important;

  line-height:1 !important;

  cursor:pointer !important;

  outline:none !important;

  box-shadow:none !important;

  transition:
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    transform .15s ease;
}


.topbar-icon-button i {
  margin:0 !important;

  padding:0 !important;

  color:inherit !important;

  font-size:17px !important;

  line-height:1 !important;
}


.topbar-icon-button:hover {
  background:#f7f2ff !important;

  border-color:#d1c1f3 !important;

  color:#6736d5 !important;
}


.topbar-icon-button:active {
  transform:scale(.95);
}


/* =========================================================
   17. BELL NOTIFICATION DOT
   YOUR HTML HAS AN EMPTY SPAN
   ========================================================= */

.notification-button span {
  position:absolute !important;

  top:7px !important;

  right:7px !important;

  width:7px !important;

  height:7px !important;

  min-width:7px !important;

  min-height:7px !important;

  padding:0 !important;

  margin:0 !important;

  border-radius:50% !important;

  background:#ee4965 !important;

  border:1.5px solid #ffffff !important;

  display:block !important;

  box-sizing:border-box !important;
}


/* =========================================================
   18. NAVBAR DIVIDER
   ========================================================= */

.topbar-divider {
  width:1px !important;

  height:34px !important;

  margin:0 6px !important;

  background:#e5e8ef !important;

  flex-shrink:0 !important;
}


/* =========================================================
   19. USER PROFILE
   ========================================================= */

.topbar-user {
  display:flex !important;

  align-items:center !important;

  gap:8px !important;

  flex-shrink:0 !important;

  margin-left:1px !important;
}


.topbar-avatar {
  width:40px !important;

  height:40px !important;

  min-width:40px !important;

  border-radius:50% !important;

  background:
    linear-gradient(
      135deg,
      #7c45e8,
      #6d35db
    ) !important;

  color:#ffffff !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  font-size:11px !important;

  font-weight:950 !important;

  box-shadow:
    0 4px 10px rgba(123,63,240,.14) !important;
}


.topbar-user-details {
  min-width:0;

  display:flex !important;

  flex-direction:column !important;

  justify-content:center !important;

  gap:2px !important;
}


.topbar-user-name {
  color:#1d2738 !important;

  font-size:11px !important;

  font-weight:950 !important;

  line-height:1.1 !important;

  white-space:nowrap !important;
}


.topbar-user-role {
  color:#929aaa !important;

  font-size:9px !important;

  font-weight:700 !important;

  line-height:1 !important;

  white-space:nowrap !important;
}


.topbar-chevron {
  margin-left:2px !important;

  color:#59667a !important;

  font-size:15px !important;

  line-height:1 !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;
}


/* =========================================================
   20. PAGE CONTENT
   ========================================================= */

.company-page-content {
  width:100% !important;

  max-width:1480px !important;

  min-width:0 !important;

  margin:0 auto !important;

  padding:27px 30px 45px !important;

  background:#f5f7fb !important;
}


/* =========================================================
   21. PAGE HEADING
   ========================================================= */

.page-heading-row {
  width:100%;

  display:flex;

  align-items:flex-end;

  justify-content:space-between;

  gap:25px;

  margin-bottom:21px;
}


.page-kicker {
  margin-bottom:8px;

  color:#6e3ad8;

  font-size:10px;

  font-weight:950;

  letter-spacing:1.2px;
}


.kicker-dot {
  display:inline-block;

  width:8px;

  height:8px;

  border-radius:50%;

  background:#7a43e6;

  margin-right:6px;
}


.page-heading-row h1 {
  margin:0;

  color:#121a2c;

  font-size:29px;

  font-weight:950;

  letter-spacing:-.5px;
}


.page-heading-row p {
  margin:7px 0 0;

  max-width:800px;

  color:#70798d;

  font-size:12px;

  font-weight:600;

  line-height:1.5;
}


.page-heading-actions {
  display:flex;

  align-items:center;

  gap:9px;

  flex-shrink:0;
}


/* =========================================================
   22. PAGE ACTION BUTTONS
   ========================================================= */

.refresh-data-button,
.add-company-button {
  height:42px;

  border-radius:9px;

  padding:0 15px;

  font-size:11px;

  font-weight:900;

  cursor:pointer;

  white-space:nowrap;
}


.refresh-data-button {
  background:#ffffff;

  border:1px solid #d8caf7;

  color:#6939d7;
}


.refresh-data-button:hover {
  background:#f8f4ff;
}


.add-company-button {
  background:#7639e6;

  border:1px solid #7639e6;

  color:#ffffff;

  box-shadow:
    0 6px 13px rgba(108,61,224,.20);
}


.add-company-button:hover {
  background:#6630d3;

  border-color:#6630d3;
}


.add-plus {
  margin-right:4px;

  font-size:17px;
}


/* =========================================================
   23. KPI CARDS
   ========================================================= */

.company-kpi-grid {
  width:100%;

  display:grid;

  grid-template-columns:
    repeat(4,minmax(0,1fr));

  gap:15px;

  margin-bottom:21px;
}


.company-kpi-card {
  min-width:0;

  min-height:137px;

  padding:18px;

  border-radius:16px;

  display:flex;

  align-items:center;

  gap:15px;

  border:1px solid;

  position:relative;

  overflow:hidden;

  box-shadow:
    0 4px 12px rgba(31,42,68,.035);
}


.total-card {
  background:#f1edff;

  border-color:#ddd2fb;
}


.active-card {
  background:#ecfbf3;

  border-color:#d0f0dd;
}


.inactive-card {
  background:#fff8e6;

  border-color:#f4e2b9;
}


.type-card {
  background:#edf5ff;

  border-color:#d7e8fb;
}


.kpi-icon {
  width:54px;

  height:54px;

  min-width:54px;

  border-radius:13px;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:22px;

  font-weight:900;
}


.total-icon {
  background:#e2d7ff;

  color:#6a35d4;
}


.active-icon {
  background:#cef2dd;

  color:#169566;
}


.inactive-icon {
  background:#ffe7b9;

  color:#c78217;
}


.type-icon {
  background:#d8eaff;

  color:#367dca;
}


.kpi-content {
  min-width:0;
}


.kpi-label {
  color:#4e5262;

  font-size:9px;

  font-weight:900;

  letter-spacing:.9px;
}


.kpi-value {
  margin-top:3px;

  color:#18213a;

  font-size:31px;

  line-height:1;

  font-weight:950;
}


.total-card .kpi-value {
  color:#5d2bc2;
}


.active-card .kpi-value {
  color:#148052;
}


.inactive-card .kpi-value {
  color:#b9780e;
}


.type-card .kpi-value {
  color:#2d70b9;
}


.kpi-description {
  margin-top:6px;

  color:#687084;

  font-size:9px;

  font-weight:650;

  line-height:1.3;
}


/* =========================================================
   24. FILTER BAR
   ========================================================= */

.company-filter-card {
  width:100%;

  min-height:69px;

  padding:12px 16px;

  margin-bottom:15px;

  background:#fff;

  border:1px solid #e0e4ec;

  border-radius:14px;

  box-shadow:
    0 3px 12px rgba(32,45,80,.035);

  display:flex;

  align-items:center;
}


.filter-left {
  width:100%;

  display:grid;

  grid-template-columns:
    auto
    minmax(250px,2fr)
    minmax(150px,1fr)
    minmax(150px,1fr)
    minmax(140px,1fr)
    auto;

  gap:9px;

  align-items:center;
}


.filter-company-count {
  display:flex;

  align-items:center;

  gap:6px;

  white-space:nowrap;
}


.filter-count-label {
  color:#6f3bd8;

  font-size:9px;

  font-weight:900;

  letter-spacing:.9px;
}


.filter-company-count strong {
  color:#19223a;

  font-size:17px;

  font-weight:950;
}


.filter-company-count span:last-child {
  color:#7d8494;

  font-size:9px;

  font-weight:600;
}


.directory-search {
  height:40px;

  border:1px solid #dfe4ec;

  border-radius:8px;

  background:#fff;

  display:flex;

  align-items:center;

  gap:7px;

  padding:0 10px;
}


.directory-search span {
  color:#6f40df;

  font-size:18px;
}


.directory-search input {
  width:100%;

  min-width:0;

  border:0;

  outline:0;

  background:transparent;

  color:#29334a;

  font-size:10px;

  font-weight:600;
}


.directory-search input::placeholder {
  color:#9299a8;
}


.company-filter-select {
  width:100%;

  height:40px;

  padding:0 9px;

  border:1px solid #dfe4ec;

  border-radius:8px;

  background:#fff;

  color:#29334a;

  font-size:10px;

  font-weight:700;

  outline:0;

  cursor:pointer;
}


.company-filter-select:focus {
  border-color:#7745df;

  box-shadow:
    0 0 0 3px rgba(119,69,223,.08);
}


.clear-filter-button {
  height:40px;

  padding:0 13px;

  border:1px solid #dfe4ec;

  border-radius:8px;

  background:#fff;

  color:#626b7c;

  font-size:10px;

  font-weight:800;

  cursor:pointer;
}


.clear-filter-button:hover {
  background:#f7f3ff;

  border-color:#d6c9f5;

  color:#6435d0;
}


/* =========================================================
   25. COMPANY DIRECTORY
   ========================================================= */

.company-directory-card {
  position:relative;

  width:100%;

  background:#fff;

  border:1px solid #dddff0;

  border-radius:16px;

  overflow:hidden;

  box-shadow:
    0 5px 16px rgba(31,42,68,.045);
}


.company-directory-card::before {
  content:"";

  display:block;

  width:100%;

  height:5px;

  background:
    linear-gradient(
      90deg,
      #7b3ff0 0%,
      #7b3ff0 25%,
      #367dcc 25%,
      #367dcc 47%,
      #18a56f 47%,
      #18a56f 68%,
      #f0a629 68%,
      #f0a629 84%,
      #e75570 84%,
      #e75570 100%
    );
}


/* =========================================================
   26. DIRECTORY HEADER
   ========================================================= */

.directory-header {
  min-height:78px;

  padding:16px 19px;

  display:flex;

  align-items:center;

  justify-content:space-between;

  border-bottom:1px solid #e6e3f0;

  background:
    linear-gradient(
      90deg,
      #faf7ff 0%,
      #ffffff 75%
    );
}


.directory-kicker {
  margin-bottom:4px;

  color:#6f39d9;

  font-size:8px;

  font-weight:950;

  letter-spacing:1.2px;
}


.directory-header h2 {
  margin:0;

  color:#172033;

  font-size:20px;

  font-weight:950;
}


.directory-header-right {
  display:flex;

  align-items:center;

  gap:12px;
}


.directory-record-count {
  padding:7px 10px;

  border-radius:8px;

  background:#f0eaff;

  border:1px solid #ddd0f7;

  color:#6b38d2;

  font-size:9px;

  font-weight:900;
}


.directory-add-button {
  height:36px;

  padding:0 13px;

  border:0;

  border-radius:8px;

  background:#7639e6;

  color:#fff;

  font-size:10px;

  font-weight:900;

  cursor:pointer;
}


.directory-add-button:hover {
  background:#6630d3;
}


/* =========================================================
   27. COMPANY TABLE
   ========================================================= */

.company-table-container {
  width:100%;

  overflow-x:auto;

  overflow-y:hidden;
}


.company-table {
  width:100%;

  min-width:1280px;

  border-collapse:collapse;

  table-layout:fixed;
}


.company-table th {
  height:47px;

  padding:0 14px;

  background:#fafbfe;

  border-bottom:1px solid #e3e5ee;

  color:#70788d;

  text-align:left;

  font-size:8px;

  font-weight:950;

  letter-spacing:.8px;

  white-space:nowrap;
}


.company-table th:nth-child(1) {
  width:19%;

  color:#6d36d9;
}


.company-table th:nth-child(2) {
  width:9%;
}


.company-table th:nth-child(3) {
  width:12%;

  color:#2e73bd;
}


.company-table th:nth-child(4) {
  width:11%;

  color:#6d36d9;
}


.company-table th:nth-child(5) {
  width:15%;

  color:#367dcc;
}


.company-table th:nth-child(6) {
  width:11%;
}


.company-table th:nth-child(7) {
  width:10%;

  color:#b7770d;
}


.company-table th:nth-child(8) {
  width:8%;

  color:#168456;
}


.company-table th:nth-child(9) {
  width:5%;

  color:#6d36d9;
}


.company-table td {
  height:70px;

  padding:10px 14px;

  border-bottom:1px solid #eceef3;

  vertical-align:middle;

  color:#2b3449;

  font-size:11px;

  font-weight:600;

  background:#fff;
}


.company-table tbody tr {
  transition:
    background .15s ease;
}


.company-table tbody tr:hover td {
  background:#fbf9ff;
}


/* =========================================================
   28. COMPANY NAME
   ========================================================= */

.company-name-cell {
  display:flex;

  align-items:center;

  gap:10px;

  min-width:0;
}


.company-avatar {
  width:40px;

  height:40px;

  min-width:40px;

  border-radius:11px;

  background:
    linear-gradient(
      135deg,
      #7b45e5,
      #6331d7
    );

  color:#fff;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:11px;

  font-weight:950;
}


.company-name {
  color:#172033;

  font-size:12px;

  font-weight:950;

  white-space:nowrap;

  overflow:hidden;

  text-overflow:ellipsis;
}


.company-subtitle {
  margin-top:3px;

  color:#8e95a5;

  font-size:8px;

  font-weight:650;
}


/* =========================================================
   29. COMPANY TABLE BADGES
   ========================================================= */

.company-id-value {
  display:inline-block;

  padding:5px 7px;

  border-radius:6px;

  background:#f3f5f9;

  border:1px solid #e5e8ee;

  color:#566177;

  font-size:9px;

  font-weight:850;
}


.industry-chip {
  display:inline-flex;

  align-items:center;

  padding:6px 9px;

  border-radius:8px;

  background:#eaf4ff;

  color:#2671bb;

  border:1px solid #d2e6fb;

  font-size:9px;

  font-weight:900;
}


.industry-chip::before {
  content:"";

  width:5px;

  height:5px;

  margin-right:5px;

  border-radius:50%;

  background:#3d8bd5;
}


.recruiter-value {
  display:inline-block;

  color:#5232a9;

  background:#f5f0ff;

  border-radius:7px;

  padding:5px 7px;

  font-size:10px;

  font-weight:850;
}


.email-value {
  display:inline-block;

  color:#4771a7;

  background:#f1f7ff;

  border-radius:7px;

  padding:5px 7px;

  font-size:9px;

  font-weight:700;

  word-break:break-word;
}


.contact-value {
  display:inline-block;

  color:#566177;

  background:#f7f8fa;

  border-radius:7px;

  padding:5px 7px;

  font-size:9px;

  font-weight:800;
}


.company-type-chip {
  display:inline-flex;

  align-items:center;

  padding:6px 9px;

  border-radius:8px;

  background:#fff3df;

  color:#a9680c;

  border:1px solid #f0dcb8;

  font-size:9px;

  font-weight:900;
}


.company-type-chip::before {
  content:"";

  width:5px;

  height:5px;

  margin-right:5px;

  border-radius:50%;

  background:#e29a2b;
}


/* =========================================================
   30. STATUS
   ========================================================= */

.company-status-chip {
  display:inline-flex;

  align-items:center;

  gap:5px;

  padding:6px 9px;

  border-radius:20px;

  font-size:9px;

  font-weight:900;

  white-space:nowrap;
}


.status-dot {
  width:6px;

  height:6px;

  border-radius:50%;
}


.company-status-active {
  background:#e4f8ed;

  color:#168455;

  border:1px solid #c7ead8;
}


.company-status-active .status-dot {
  background:#1daf6c;
}


.company-status-inactive {
  background:#fdebed;

  color:#c44350;

  border:1px solid #f2ced4;
}


.company-status-inactive .status-dot {
  background:#df5260;
}


.company-status-other {
  background:#fff1dc;

  color:#a96a12;

  border:1px solid #f0dcb8;
}


.company-status-other .status-dot {
  background:#d98b20;
}


/* =========================================================
   31. VIEW BUTTON
   ========================================================= */

.view-company-button {
  height:33px;

  padding:0 11px;

  border:1px solid #d5c8f5;

  border-radius:8px;

  background:#f8f4ff;

  color:#6337cd;

  font-size:9px;

  font-weight:900;

  cursor:pointer;

  white-space:nowrap;

  transition:
    background .15s ease,
    color .15s ease,
    border-color .15s ease;
}


.view-company-button:hover {
  background:#7639e6;

  border-color:#7639e6;

  color:#fff;
}


.view-company-button span {
  margin-left:3px;

  font-size:12px;
}


/* =========================================================
   32. EMPTY STATE
   ========================================================= */

.empty-state {
  padding:55px 20px;

  text-align:center;
}


.empty-state-icon {
  width:52px;

  height:52px;

  margin:0 auto 12px;

  border-radius:12px;

  background:#eee8ff;

  color:#7040d9;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:22px;

  font-weight:900;
}


.empty-state h3 {
  margin:0;

  color:#20283b;

  font-size:17px;

  font-weight:950;
}


.empty-state p {
  margin:6px 0 15px;

  color:#81899a;

  font-size:11px;

  font-weight:600;
}


.empty-add-button {
  height:36px;

  padding:0 13px;

  border:0;

  border-radius:8px;

  background:#7639e6;

  color:#fff;

  font-size:10px;

  font-weight:900;

  cursor:pointer;
}


/* =========================================================
   33. MODAL OVERLAY
   ========================================================= */

.company-modal-overlay {
  position:fixed !important;

  inset:0 !important;

  z-index:50000 !important;

  background:rgba(16,12,39,.58) !important;

  display:flex !important;

  align-items:center !important;

  justify-content:center !important;

  padding:20px !important;
}


.company-modal {
  width:760px;

  max-width:95vw;

  max-height:90vh;

  overflow-y:auto;

  background:#fff;

  border:1px solid #e2e5ed;

  border-radius:15px;

  box-shadow:
    0 20px 55px rgba(16,12,39,.22);
}


.add-company-modal {
  width:820px;
}


/* =========================================================
   34. MODAL HEADER
   ========================================================= */

.modal-header {
  min-height:82px;

  padding:15px 19px;

  display:flex;

  align-items:center;

  justify-content:space-between;

  border-bottom:1px solid #e7e9ef;

  background:#faf8ff;
}


.add-modal-header {
  background:#f8fbff;
}


.modal-company-title {
  display:flex;

  align-items:center;

  gap:11px;
}


.modal-company-avatar {
  width:46px;

  height:46px;

  min-width:46px;

  border-radius:11px;

  background:
    linear-gradient(
      135deg,
      #7a43e6,
      #6330d4
    );

  color:#fff;

  display:flex;

  align-items:center;

  justify-content:center;

  font-size:12px;

  font-weight:950;
}


.add-avatar {
  background:#22a76b;

  font-size:25px;
}


.modal-company-title h2 {
  margin:0;

  color:#172033;

  font-size:18px;

  font-weight:950;
}


.modal-company-title p {
  margin:3px 0 0;

  color:#7f8798;

  font-size:10px;

  font-weight:600;
}


.modal-close {
  width:35px;

  height:35px;

  border:1px solid #dfe3eb;

  border-radius:8px;

  background:#fff;

  color:#6a7284;

  font-size:21px;

  cursor:pointer;
}


.modal-close:hover {
  background:#f4efff;

  color:#6636d4;
}


.modal-body {
  padding:20px;
}


.modal-section-heading {
  margin-bottom:11px;

  color:#6436d0;

  font-size:12px;

  font-weight:950;
}


/* =========================================================
   35. MODAL DETAILS
   ========================================================= */

.detail-grid {
  display:grid;

  grid-template-columns:
    repeat(4,1fr);

  gap:10px;

  margin-bottom:22px;
}


.detail-card {
  padding:12px;

  border-radius:9px;

  border-left:3px solid;
}


.detail-card span {
  display:block;

  color:#7b8496;

  font-size:8px;

  font-weight:800;

  text-transform:uppercase;
}


.detail-card strong {
  display:block;

  margin-top:6px;

  color:#263047;

  font-size:11px;

  font-weight:950;
}


.purple-detail {
  background:#f0eaff;

  border-color:#7242dc;
}


.blue-detail {
  background:#e9f3ff;

  border-color:#3985d2;
}


.orange-detail {
  background:#fff2df;

  border-color:#df8a1d;
}


.green-detail {
  background:#e6f8ef;

  border-color:#20a66b;
}


.recruiter-details {
  border:1px solid #e1e5eb;

  border-radius:9px;

  overflow:hidden;
}


.detail-row {
  min-height:46px;

  padding:0 13px;

  display:flex;

  align-items:center;

  justify-content:space-between;

  gap:20px;

  border-bottom:1px solid #e9ebef;
}


.detail-row:last-child {
  border-bottom:0;
}


.detail-row span {
  color:#7b8496;

  font-size:10px;

  font-weight:750;
}


.detail-row strong {
  color:#263047;

  font-size:10px;

  font-weight:900;

  text-align:right;
}


/* =========================================================
   36. MODAL FOOTER
   ========================================================= */

.modal-footer {
  padding:13px 19px;

  border-top:1px solid #e7e9ef;

  display:flex;

  justify-content:flex-end;

  gap:8px;
}


.modal-close-button {
  height:37px;

  padding:0 14px;

  border:1px solid #dfe3eb;

  border-radius:8px;

  background:#fff;

  color:#596276;

  font-size:10px;

  font-weight:850;

  cursor:pointer;
}


.modal-close-button:hover {
  background:#f7f4ff;

  color:#6335d0;
}


/* =========================================================
   37. ADD COMPANY FORM
   ========================================================= */

.add-company-form {
  display:grid;

  grid-template-columns:
    repeat(2,1fr);

  gap:14px;
}


.form-group {
  display:flex;

  flex-direction:column;
}


.form-group.full-width {
  grid-column:1 / -1;
}


.form-group label {
  margin-bottom:6px;

  color:#3e475b;

  font-size:10px;

  font-weight:900;
}


.form-group label span {
  color:#d8484e;
}


.form-group input,
.form-group select {
  width:100%;

  height:40px;

  padding:0 10px;

  border:1px solid #d8dee8;

  border-radius:8px;

  background:#fff;

  color:#283148;

  font-size:10px;

  font-weight:650;

  outline:0;
}


.form-group input:focus,
.form-group select:focus {
  border-color:#7545df;

  box-shadow:
    0 0 0 3px rgba(117,69,223,.09);
}


.add-company-message {
  margin-top:13px;

  padding:10px 12px;

  border-radius:8px;

  background:#fff0dc;

  color:#9a610c;

  font-size:10px;

  font-weight:800;
}


.save-company-button {
  height:37px;

  padding:0 15px;

  border:0;

  border-radius:8px;

  background:#7639e6;

  color:#fff;

  font-size:10px;

  font-weight:900;

  cursor:pointer;
}


.save-company-button:hover {
  background:#6630d3;
}


.save-company-button:disabled {
  opacity:.55;

  cursor:not-allowed;
}


/* =========================================================
   38. AI WIDGET
   ========================================================= */

.company-ai-widget {
  position:fixed !important;

  right:22px !important;

  bottom:18px !important;

  z-index:2147483646 !important;
}


/* =========================================================
   39. COLLAPSED SIDEBAR
   ========================================================= */

.campus360-company-app.sidebar-collapsed
.company-sidebar {
  width:0 !important;

  min-width:0 !important;

  max-width:0 !important;

  transform:translateX(-100%) !important;

  opacity:0 !important;

  pointer-events:none !important;

  overflow:hidden !important;

  border-right:0 !important;
}


.campus360-company-app.sidebar-collapsed
.company-main {
  left:0 !important;

  width:100vw !important;
}


/* =========================================================
   40. LARGE SCREEN
   ========================================================= */

@media (min-width:1500px) {

  .company-page-content {
    max-width:1480px !important;

    padding-left:30px !important;

    padding-right:30px !important;
  }

}


/* =========================================================
   41. MEDIUM DESKTOP
   ========================================================= */

@media (max-width:1250px) {

  .company-page-content {
    max-width:none !important;

    width:100% !important;
  }


  .company-kpi-grid {
    grid-template-columns:
      repeat(2,minmax(0,1fr));
  }


  .filter-left {
    grid-template-columns:
      auto
      minmax(220px,2fr)
      minmax(140px,1fr)
      minmax(140px,1fr)
      auto;
  }


  .global-search {
    width:260px !important;

    min-width:190px !important;
  }

}


/* =========================================================
   42. TABLET
   ========================================================= */

@media (max-width:1000px) {

  .company-sidebar {
    width:210px !important;

    min-width:210px !important;

    max-width:210px !important;
  }


  .company-main {
    left:210px !important;

    width:calc(100vw - 210px) !important;
  }


  .company-page-content {
    padding-left:20px !important;

    padding-right:20px !important;
  }


  .page-heading-row {
    align-items:flex-start;

    flex-direction:column;
  }


  .page-heading-actions {
    width:100%;

    justify-content:flex-start;
  }


  .global-search {
    width:220px !important;

    min-width:150px !important;
  }

}


/* =========================================================
   43. SMALL TABLET
   ========================================================= */

@media (max-width:780px) {

  .company-sidebar {
    width:76px !important;

    min-width:76px !important;

    max-width:76px !important;
  }


  .company-main {
    left:76px !important;

    width:calc(100vw - 76px) !important;
  }


  .brand-text,
  .profile-info,
  .nav-section-title,
  .nav-label,
  .nav-count {
    display:none !important;
  }


  .sidebar-brand {
    justify-content:center;

    padding-left:8px !important;

    padding-right:8px !important;
  }


  .tpo-profile {
    justify-content:center;

    margin-left:8px !important;

    margin-right:8px !important;

    padding-left:8px !important;

    padding-right:8px !important;
  }


  .sidebar-nav-item {
    justify-content:center;

    padding-left:8px !important;

    padding-right:8px !important;
  }


  .company-page-content {
    padding-left:12px !important;

    padding-right:12px !important;
  }


  .global-search {
    width:180px !important;

    min-width:140px !important;
  }


  .topbar-user-details,
  .topbar-chevron {
    display:none !important;
  }


  .company-kpi-grid {
    grid-template-columns:1fr;
  }


  .filter-left {
    grid-template-columns:1fr;
  }


  .filter-company-count {
    justify-content:flex-start;
  }


  .detail-grid {
    grid-template-columns:
      repeat(2,1fr);
  }

}


/* =========================================================
   44. MOBILE
   ========================================================= */

@media (max-width:560px) {

  .company-sidebar {
    width:0 !important;

    min-width:0 !important;

    max-width:0 !important;

    transform:translateX(-100%) !important;

    overflow:hidden !important;
  }


  .company-main {
    left:0 !important;

    width:100vw !important;
  }


  .company-topbar {
    height:68px !important;

    min-height:68px !important;

    padding:0 12px !important;
  }


  .breadcrumb-small {
    display:none !important;
  }


  .breadcrumb-title {
    font-size:14px !important;
  }


  .global-search {
    display:none !important;
  }


  .topbar-divider {
    display:none !important;
  }


  .topbar-user-details,
  .topbar-chevron {
    display:none !important;
  }


  .company-page-content {
    padding:
      18px
      10px
      35px !important;
  }


  .page-heading-row h1 {
    font-size:24px;
  }


  .page-heading-row p {
    font-size:11px;
  }


  .page-heading-actions {
    width:100%;

    flex-wrap:wrap;
  }


  .refresh-data-button,
  .add-company-button {
    flex:1;
  }


  .directory-header {
    align-items:flex-start;

    flex-direction:column;

    gap:10px;
  }


  .directory-header-right {
    width:100%;

    justify-content:space-between;
  }


  .detail-grid {
    grid-template-columns:1fr;
  }


  .add-company-form {
    grid-template-columns:1fr;
  }


  .form-group.full-width {
    grid-column:auto;
  }

}

sp_widget.script:
(function() {


  /* =====================================================
     COMPANY MASTER TABLE
  ====================================================== */

  var TABLE_NAME =
    "x_snc_campus360_company_master";


  var testGR =
    new GlideRecord(TABLE_NAME);


  if (!testGR.isValid()) {

    TABLE_NAME =
      "company_master";

    testGR =
      new GlideRecord(TABLE_NAME);

  }


  /* =====================================================
     DEFAULT DATA
  ====================================================== */

  data.companies = [];

  data.industries = [];

  data.companyTypes = [];

  data.statuses = [
    "Active",
    "Inactive"
  ];


  data.summary = {

    totalCompanies: 0,

    activeCompanies: 0,

    inactiveCompanies: 0,

    companyTypes: 0

  };


  data.success = false;

  data.message = "";


  /* =====================================================
     HELPERS
  ====================================================== */

  function clean(value) {

    if (
      value === null ||
      typeof value === "undefined"
    ) {

      return "";

    }

    return String(value).trim();

  }


  function getDisplay(gr, fieldName) {

    try {

      if (
        gr[fieldName] &&
        typeof
          gr[fieldName].getDisplayValue ===
          "function"
      ) {

        return clean(
          gr[fieldName]
            .getDisplayValue()
        );

      }

    } catch (e) {}


    try {

      if (
        gr[fieldName] &&
        typeof
          gr[fieldName].getValue ===
          "function"
      ) {

        return clean(
          gr[fieldName]
            .getValue()
        );

      }

    } catch (e2) {}


    return "";

  }


  function addUnique(array, value) {

    value = clean(value);

    if (!value) {
      return;
    }


    var exists = false;


    for (
      var i = 0;
      i < array.length;
      i++
    ) {

      if (
        String(array[i]).toLowerCase() ===
        String(value).toLowerCase()
      ) {

        exists = true;

        break;

      }

    }


    if (!exists) {

      array.push(value);

    }

  }


  function sortStrings(array) {

    array.sort(
      function(a, b) {

        return String(a)
          .toLowerCase()
          .localeCompare(
            String(b).toLowerCase()
          );

      }
    );

  }


  /* =====================================================
     LOAD COMPANIES
  ====================================================== */

  function loadCompanies() {

    data.companies = [];

    data.industries = [];

    data.companyTypes = [];


    var gr =
      new GlideRecord(TABLE_NAME);


    if (!gr.isValid()) {

      data.success = false;

      data.message =
        "Company Master table was not found.";

      return;

    }


    gr.orderBy("company_name");

    gr.query();


    while (gr.next()) {


      var company = {

        sys_id:
          clean(
            gr.getUniqueValue()
          ),

        company_name:
          getDisplay(
            gr,
            "company_name"
          ),

        company_id:
          getDisplay(
            gr,
            "company_id"
          ),

        industry:
          getDisplay(
            gr,
            "industry"
          ),

        recruiter_name:
          getDisplay(
            gr,
            "recruiter_name"
          ),

        recruiter_email:
          getDisplay(
            gr,
            "recruiter_email"
          ),

        contact_number:
          getDisplay(
            gr,
            "contact_number"
          ),

        company_type:
          getDisplay(
            gr,
            "company_type"
          ),

        status:
          getDisplay(
            gr,
            "status"
          )

      };


      data.companies.push(
        company
      );


      /* INDUSTRY */

      addUnique(
        data.industries,
        company.industry
      );


      /* COMPANY TYPE */

      addUnique(
        data.companyTypes,
        company.company_type
      );


      /* TOTAL */

      data.summary.totalCompanies++;


      /* ACTIVE */

      if (
        String(company.status)
          .toLowerCase()
          .trim() ===
        "active"
      ) {

        data.summary.activeCompanies++;

      }


      /* INACTIVE */

      if (
        String(company.status)
          .toLowerCase()
          .trim() ===
        "inactive"
      ) {

        data.summary.inactiveCompanies++;

      }

    }


    sortStrings(
      data.industries
    );

    sortStrings(
      data.companyTypes
    );


    data.summary.companyTypes =
      data.companyTypes.length;


    data.success = true;

  }


  /* =====================================================
     ADD COMPANY
  ====================================================== */

  if (
    input &&
    input.action ===
      "add_company"
  ) {


    var incoming =
      input.company || {};


    var companyName =
      clean(
        incoming.company_name
      );


    var companyId =
      clean(
        incoming.company_id
      );


    /* REQUIRED COMPANY NAME */

    if (!companyName) {

      data.success = false;

      data.message =
        "Company Name is required.";

      loadCompanies();

      return;

    }


    /* REQUIRED COMPANY ID */

    if (!companyId) {

      data.success = false;

      data.message =
        "Company ID is required.";

      loadCompanies();

      return;

    }


    /* VALIDATE TABLE */

    var insertGR =
      new GlideRecord(
        TABLE_NAME
      );


    if (!insertGR.isValid()) {

      data.success = false;

      data.message =
        "Company Master table was not found.";

      return;

    }


    /* =================================================
       DUPLICATE COMPANY ID CHECK
    ================================================= */

    if (
      insertGR.isValidField(
        "company_id"
      )
    ) {

      var duplicateGR =
        new GlideRecord(
          TABLE_NAME
        );


      duplicateGR.addQuery(
        "company_id",
        companyId
      );


      duplicateGR.setLimit(1);

      duplicateGR.query();


      if (duplicateGR.next()) {

        data.success = false;

        data.message =
          "A company with this Company ID already exists.";

        loadCompanies();

        return;

      }

    }


    /* =================================================
       INITIALIZE
    ================================================= */

    insertGR.initialize();


    /* COMPANY NAME */

    if (
      insertGR.isValidField(
        "company_name"
      )
    ) {

      insertGR.setValue(
        "company_name",
        companyName
      );

    }


    /* COMPANY ID */

    if (
      insertGR.isValidField(
        "company_id"
      )
    ) {

      insertGR.setValue(
        "company_id",
        companyId
      );

    }


    /* INDUSTRY */

    if (
      insertGR.isValidField(
        "industry"
      )
    ) {

      insertGR.setValue(
        "industry",
        clean(
          incoming.industry
        )
      );

    }


    /* RECRUITER NAME */

    if (
      insertGR.isValidField(
        "recruiter_name"
      )
    ) {

      insertGR.setValue(
        "recruiter_name",
        clean(
          incoming.recruiter_name
        )
      );

    }


    /* RECRUITER EMAIL */

    if (
      insertGR.isValidField(
        "recruiter_email"
      )
    ) {

      insertGR.setValue(
        "recruiter_email",
        clean(
          incoming.recruiter_email
        )
      );

    }


    /* CONTACT NUMBER */

    if (
      insertGR.isValidField(
        "contact_number"
      )
    ) {

      insertGR.setValue(
        "contact_number",
        clean(
          incoming.contact_number
        )
      );

    }


    /* COMPANY TYPE */

    if (
      insertGR.isValidField(
        "company_type"
      )
    ) {

      insertGR.setValue(
        "company_type",
        clean(
          incoming.company_type
        )
      );

    }


    /* STATUS */

    if (
      insertGR.isValidField(
        "status"
      )
    ) {

      var companyStatus =
        clean(
          incoming.status
        );


      if (!companyStatus) {

        companyStatus =
          "Active";

      }


      insertGR.setValue(
        "status",
        companyStatus
      );

    }


    /* INSERT */

    var insertedSysId =
      insertGR.insert();


    if (insertedSysId) {

      data.success = true;

      data.message =
        "Company added successfully.";

    } else {

      data.success = false;

      data.message =
        "Company could not be added.";

    }


    /* RELOAD */

    loadCompanies();

    return;

  }


  /* =====================================================
     NORMAL PAGE LOAD
  ====================================================== */

  loadCompanies();


})();
